# --- find_eye_width (MATLAB lines 5723–5785) ---

# ============================================================
# MATLAB→Python translation notes for find_eye_width
# MATLAB lines: 5723–5785
# ============================================================
# eye_contour is (N×2): column 0 = top eye, column 1 = bottom eye.
# MATLAB 1-based indexing: eye_contour(half_UI:-1:1, 1) → Python eye_contour[half_UI-1::-1, 0].
# half_UI appears in both the left slice (reversed) and right slice (forward).
# vref_intersect: linear interpolation between the two samples bracketing the vref crossing.
#   x_in is 1-based within the passed slice.
# ============================================================



def _find_eye_width__vref_intersect(eye_col_1d, x_in_1based, vref):
    x = x_in_1based
    m1 = eye_col_1d[x - 1] - eye_col_1d[x - 2]
    b1 = eye_col_1d[x - 1] - m1 * x
    return (vref - b1) / m1


def find_eye_width(eye_contour, half_UI, samples_per_UI, vref):
    eye_contour = np.asarray(eye_contour)

    # Left eye (top)
    left_top = eye_contour[half_UI - 1::-1, 0]
    idx = np.where(left_top < vref)[0]
    if len(idx) == 0:
        L1 = half_UI
    elif idx[0] == 0:
        L1 = 0
    else:
        vc = int(idx[0]) + 1  # 1-based
        x_in = half_UI - vc + 2
        INT = _find_eye_width__vref_intersect(eye_contour[:half_UI, 0], x_in, vref)
        L1 = half_UI - INT

    # Left eye (bottom)
    left_bot = eye_contour[half_UI - 1::-1, 1]
    idx = np.where(left_bot > vref)[0]
    if len(idx) == 0:
        L0 = half_UI
    elif idx[0] == 0:
        L0 = 0
    else:
        vc = int(idx[0]) + 1
        x_in = half_UI - vc + 2
        INT = _find_eye_width__vref_intersect(eye_contour[:half_UI, 1], x_in, vref)
        L0 = half_UI - INT

    # Right eye (top)
    right_top = eye_contour[half_UI - 1:, 0]
    idx = np.where(right_top < vref)[0]
    if len(idx) == 0:
        R1 = samples_per_UI - half_UI
    elif idx[0] == 0:
        R1 = 0
    else:
        vc = int(idx[0]) + 1
        INT = _find_eye_width__vref_intersect(eye_contour[half_UI - 1:, 0], vc, vref) + half_UI - 1
        R1 = INT - half_UI

    # Right eye (bottom)
    right_bot = eye_contour[half_UI - 1:, 1]
    idx = np.where(right_bot > vref)[0]
    if len(idx) == 0:
        R0 = samples_per_UI - half_UI
    elif idx[0] == 0:
        R0 = 0
    else:
        vc = int(idx[0]) + 1
        INT = _find_eye_width__vref_intersect(eye_contour[half_UI - 1:, 1], vc, vref) + half_UI - 1
        R0 = INT - half_UI

    Left_EW = min(L1, L0)
    Right_EW = min(R1, R0)
    return Left_EW, Right_EW



# --- findbankloc (MATLAB lines 5786–5937) ---

def findbankloc(hisi, idx_st, idx_en, tap_bk, curval, bmaxg, N_bg):
    """Find optimal DFE bank locations within hisi[idx_st-1 : idx_en].

    Parameters use MATLAB 1-based convention (idx_st, idx_en).
    Returns 0-based indices into hisi (Python convention).

    Algorithm:
      Build ndiff[j] = sum of (h0^2 - h1^2) for tap bank starting at j,
      where h1 = max(0, h0 - bmaxg*curval).  Choose N_bg non-adjacent banks
      greedily by highest ndiff; enforce minimum gap of tap_bk between banks.
    """
    hisi = np.asarray(hisi, dtype=float).ravel()
    len_ = idx_en - idx_st + 1
    h0 = np.abs(hisi[idx_st - 1:idx_en])   # length len_
    h1 = np.maximum(0.0, h0 - bmaxg * curval)
    if curval < 0:
        h1 = np.zeros(len_)

    n_bins = len_ - tap_bk + 1             # number of valid bank start positions
    h0n = np.zeros(n_bins)
    h1n = np.zeros(n_bins)
    for ii in range(tap_bk):
        h0n += h0[ii:ii + n_bins] ** 2
        h1n += h1[ii:ii + n_bins] ** 2
    ndiff = h0n - h1n                       # 0-based indices 0..n_bins-1

    MIN_E = -np.inf
    # idx stores 0-based ndiff positions; -1 = not yet placed
    idx = np.full(tap_bk * N_bg, -1, dtype=int)
    # Shortcut check: are 0..(N_bg-1)*tap_bk the top (N_bg-1)*tap_bk+1 entries?
    ordered_set = np.arange((N_bg - 1) * tap_bk + 1)
    set_next_bank = -1   # -1 = not pending

    for k in range(N_bg):
        val_sort = np.argsort(-ndiff, kind='stable')       # 0-based, descending

        if k == 0:
            ns = len(ordered_set)
            if np.array_equal(np.sort(val_sort[:ns]), ordered_set):
                idx = np.arange(N_bg * tap_bk)
                break

        if set_next_bank >= 0:
            new_bank = np.arange(set_next_bank, set_next_bank + tap_bk)
            idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
            set_next_bank = -1
            ndiff[new_bank] = MIN_E
            b_start = new_bank[0] - tap_bk + 1
            b_end = new_bank[0] - 1
            badV = _findbankloc__make_badV(b_start, b_end)
            if len(badV):
                ndiff[badV] = MIN_E
            continue

        new_bank = np.arange(val_sort[0], val_sort[0] + tap_bk)
        if k == N_bg - 1:
            idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
            break

        placed = idx[:tap_bk * k]           # already-placed 0-based positions
        badV = np.array([], dtype=int)
        do_it_again = True
        first_time = True
        num_loops = 0
        while do_it_again:
            do_it_again = False
            if num_loops > len(ndiff):
                break
            b_start = new_bank[0] - tap_bk + 1
            b_end = new_bank[0] - 1
            badV = _findbankloc__make_badV(b_start, b_end)
            # remove already-placed indices from badV
            if len(badV) and len(placed):
                badV = badV[~np.isin(badV, placed)]
            goodV_idx = new_bank[0] - tap_bk

            if len(badV) > 0:
                if not first_time:
                    val_sort = np.argsort(-ndiff, kind='stable')
                first_time = False
                checkV = np.concatenate([badV, new_bank])
                badV_pos = np.array(
                    [int(np.where(val_sort == v)[0][0]) for v in badV]
                )

                found_goodV = False
                ii_found = len(val_sort) - 1
                for ii_vs in range(len(val_sort)):
                    if val_sort[ii_vs] == goodV_idx:
                        found_goodV = True
                        ii_found = ii_vs
                        break
                    if not np.any(val_sort[ii_vs] == checkV):
                        ii_found = ii_vs
                        break

                if (not found_goodV) and (len(badV_pos) > 0) and (np.min(badV_pos) < ii_found):
                    do_it_again = True
                    ndiff[new_bank[0]] = MIN_E
                    new_bank = np.arange(val_sort[1], val_sort[1] + tap_bk)
                if found_goodV:
                    set_next_bank = goodV_idx
            num_loops += 1

        ndiff[new_bank] = MIN_E
        idx[tap_bk * k: tap_bk * (k + 1)] = new_bank
        if len(badV):
            ndiff[badV] = MIN_E

    # Convert 0-based ndiff positions → 0-based hisi positions
    return idx + (idx_st - 1)


def _findbankloc__make_badV(b_start, b_end):
    """Build array of 0-based indices from b_start to b_end inclusive (handles negatives)."""
    if b_end < 0:
        return np.array([], dtype=int)
    start = max(0, b_start)
    return np.arange(start, b_end + 1, dtype=int)



# --- compute_hard_cap (MATLAB lines 5788–5794) ---

# ============================================================
# MATLAB→Python translation notes for compute_hard_cap
# MATLAB lines: 5788-5794 (com_ieee8023_4p15p0_adaptive_local_search.m)
# NEW in Hansel D'silva's adaptive-local-search branch.
# ============================================================
# Tiny helper: the hard cap on the raw TX-tap L1 distance used by the
# adaptive local search. round() is MATLAB round (half away from zero).
# Returns NaN when capping is disabled, matching the MATLAB return.
# ============================================================



def _compute_hard_cap__mround(x):
    """MATLAB round(): half away from zero."""
    return int(np.floor(float(x) + 0.5)) if x >= 0 else int(np.ceil(float(x) - 0.5))


def compute_hard_cap(use_hard_cap, mul, LSV, min_radius):
    """Hard cap for the raw TX L1 distance (MATLAB lines 5788-5794)."""
    if use_hard_cap:
        return max(min_radius, _compute_hard_cap__mround(mul * LSV))
    return float('nan')



