# --- s21_pkg (MATLAB lines 10900–11075) ---

# ============================================================
# MATLAB→Python translation notes for s21_pkg
# MATLAB lines: 10900–11075
# ============================================================
# Concatenates TX pkg + channel + RX pkg, computes VTF (Eq 93A-18).
# Inlines: make_full_pkg (→ make_pkg, synth_tline, combines4p), Bessel_Thomson.
#
# Key paths:
#   INC_PACKAGE=0: return s21 directly (warning)
#   RX_CALIBRATION=1 and channel_number=2: only RX pkg (channel+RX)
#   Normal: (TX pkg not skipped): TX+channel; then +RX pkg
#   PSDRXCAL and channel==num_s4p_files: TX pkg bypassed (identity)
#   Mode 'dc'/'cd': RTX/RRX/Z0gamma adjustments
#
# VTF (Eq 93A-18):
#   s21p = H_t * s21 * (1-gamma_tx)*(1+gamma_rx) /
#          (1 - s11*gamma_tx - s22*gamma_rx
#             - s21*s12*gamma_tx*gamma_rx
#             + s11*s22*gamma_tx*gamma_rx)
#
# SCH returned as SimpleNamespace with fields:
#   .Frequencies, .Parameters (shape [2,2,nfreq]), .NumPorts, .Impedance
# ============================================================



# ---- inlined helpers --------------------------------------------------------

def _s21_pkg__synth_tline(f, Z_c, Z_0, gamma_coeff, tau, d):
    f = np.asarray(f, dtype=float)
    f_GHz = f / 1e9
    eps_val = np.finfo(float).tiny
    f_GHz_s = np.where(f_GHz == 0, eps_val, f_GHz)
    gamma_coeff = np.asarray(gamma_coeff, dtype=float).ravel()
    gamma0, a1, a2 = gamma_coeff[0], gamma_coeff[1], gamma_coeff[2]
    gamma_1 = a1 * (1.0 + 1j)
    gamma_2 = a2 * (1.0 - 2j / np.pi * np.log(f_GHz_s)) + 2j * np.pi * float(tau)
    gamma = gamma0 + gamma_1 * np.sqrt(f_GHz_s) + gamma_2 * f_GHz_s
    gamma = np.where(f_GHz == 0, gamma0, gamma)
    if float(d) == 0.0:
        rho_rl = 0.0
    else:
        rho_rl = (float(Z_c) - 2.0 * float(Z_0)) / (float(Z_c) + 2.0 * float(Z_0))
    exp_gd = np.exp(-float(d) * gamma)
    denom = 1.0 - rho_rl ** 2 * exp_gd ** 2
    s11 = rho_rl * (1.0 - exp_gd ** 2) / denom
    s21 = (1.0 - rho_rl ** 2) * exp_gd / denom
    return s11, s21, s21, s11


def _s21_pkg__combines4p(s11_1, s12_1, s21_1, s22_1, s11_2, s12_2, s21_2, s22_2):
    N = 1.0 - s22_1 * s11_2
    s11 = s11_1 + s12_1 * s21_1 * s11_2 / N
    s12 = s12_1 * s12_2 / N
    s21 = s21_2 * s21_1 / N
    s22 = s22_2 + s12_2 * s21_2 * s22_1 / N
    return s11, s12, s21, s22


def _s21_pkg__make_pkg(f, pkg_len, cpad, cball, pkg_z, pkg_param, lcomp=0.0, cbump=0.0):
    f = np.asarray(f, dtype=float)
    eps_val = np.finfo(float).tiny
    f = np.where(f < eps_val, eps_val, f)
    zref = float(pkg_param.Z0)
    tau = float(pkg_param.pkg_tau)
    gamma_coeff = np.asarray(pkg_param.pkg_gamma0_a1_a2, dtype=float).ravel()

    jw_cpad_z = 1j * 2 * np.pi * f * float(cpad) * zref
    s11pad = -jw_cpad_z / (2.0 + jw_cpad_z)
    s21pad = 2.0 / (2.0 + jw_cpad_z)
    s12pad, s22pad = s21pad.copy(), s11pad.copy()

    if float(lcomp) > 0.0:
        jw_lcomp_z = 1j * 2 * np.pi * f * float(lcomp) / zref
        s11comp = jw_lcomp_z / (2.0 + jw_lcomp_z)
        s21comp = 2.0 / (2.0 + jw_lcomp_z)
        s11pad, s12pad, s21pad, s22pad = _s21_pkg__combines4p(
            s11pad, s12pad, s21pad, s22pad,
            s11comp, s21comp, s21comp, s11comp)

    if float(cbump) > 0.0:
        jw_cbump_z = 1j * 2 * np.pi * f * float(cbump) * zref
        s11bump = -jw_cbump_z / (2.0 + jw_cbump_z)
        s21bump = 2.0 / (2.0 + jw_cbump_z)
        s11pad, s12pad, s21pad, s22pad = _s21_pkg__combines4p(
            s11pad, s12pad, s21pad, s22pad,
            s11bump, s21bump, s21bump, s11bump)

    S11, S12, S21, S22 = _s21_pkg__synth_tline(f, float(pkg_z), zref, gamma_coeff, tau, float(pkg_len))
    s11out1, s12out1, s21out1, s22out1 = _s21_pkg__combines4p(
        s11pad, s12pad, s21pad, s22pad, S11, S12, S21, S22)

    jw_cball_z = 1j * 2 * np.pi * f * float(cball) * zref
    s11ball = -jw_cball_z / (2.0 + jw_cball_z)
    s21ball = 2.0 / (2.0 + jw_cball_z)
    s11out, s12out, s21out, s22out = _s21_pkg__combines4p(
        s11out1, s12out1, s21out1, s22out1,
        s11ball, s21ball, s21ball, s11ball)
    return s11out, s12out, s21out, s22out


def _s21_pkg__make_full_pkg(type_, faxis, param, channel_type, mode='dd', include_die=1):
    faxis = np.asarray(faxis, dtype=float)
    pkg_param = copy.copy(param)

    pkg_name_list = getattr(param, 'PKG_NAME', None)
    if pkg_name_list is not None and len(pkg_name_list) > 0:
        type_upper = str(type_).upper()
        pkg_name = pkg_name_list[0] if type_upper == 'TX' else pkg_name_list[1]
        pkg_struct = param.PKG[pkg_name]
        for field in ['pkg_gamma0_a1_a2', 'pkg_tau']:
            setattr(pkg_param, field, getattr(pkg_struct, field))

    C_diepad = np.asarray(param.C_diepad, dtype=float)
    C_pkg_board = np.asarray(param.C_pkg_board, dtype=float).ravel()
    L_comp = np.asarray(param.L_comp, dtype=float)
    C_bump = np.asarray(param.C_bump, dtype=float).ravel()

    if not include_die:
        C_diepad = C_diepad * 0
        L_comp = L_comp * 0
        C_bump = C_bump * 0

    z_p = np.atleast_2d(np.asarray(param.z_p_next_cases))
    ncases, mele = z_p.shape
    is_vector = C_diepad.ndim == 1 or (C_diepad.ndim == 2 and min(C_diepad.shape) == 1)
    C_flat = C_diepad.ravel()
    L_flat = L_comp.ravel()

    if is_vector:
        Cd_Tx = float(C_flat[0]) if len(C_flat) > 0 else 0.0
        Cd_Rx = float(C_flat[1]) if len(C_flat) > 1 else 0.0
        Lcomp_Tx = float(L_flat[0]) if len(L_flat) > 0 else 0.0
        Lcomp_Rx = float(L_flat[1]) if len(L_flat) > 1 else 0.0
        extra_LC = 0
        num_blocks = mele
    else:
        C2d = C_diepad.reshape(2, -1)
        L2d = L_comp.reshape(2, -1)
        Cd_Tx_arr = C2d[0, :]
        Cd_Rx_arr = C2d[1, :]
        Lcomp_Tx = L2d[0, :]
        Lcomp_Rx = L2d[1, :]
        extra_LC = len(Cd_Tx_arr) - 1
        num_blocks = mele + extra_LC
        Cd_Tx, Cd_Rx = Cd_Tx_arr, Cd_Rx_arr

    insert_zeros = np.zeros(extra_LC)

    def _to_scalar(v):
        return float(np.asarray(v).ravel()[0])

    pkg_Z_c = np.asarray(param.pkg_Z_c, dtype=float)
    type_upper = str(type_).upper()

    if type_upper == 'TX':
        if mele == 1:
            Cpad = np.array([_to_scalar(Cd_Tx)])
            Lcomp = np.array([_to_scalar(Lcomp_Tx)])
            Cbump = np.array([float(C_bump[0])])
            Cball = np.array([float(C_pkg_board[0])])
            Zpkg = np.array([float(pkg_Z_c.ravel()[0])])
        elif mele == 4:
            # MATLAB: Cpad=[Cd_Tx 0 0 0]; Lcomp=[Lcomp_Tx 0 0 0] (L8390-8391).
            # Cd_Tx/Lcomp_Tx are ROW VECTORS when C_d/L_comp are a 2xN matrix
            # (N die LC sections per side), so MATLAB yields len(Cd_Tx)+3 entries,
            # matching num_blocks = mele + extra_LC. _to_scalar() kept only the
            # first section, dropping the rest of the die LC network.
            Cpad = np.concatenate([np.atleast_1d(np.asarray(Cd_Tx, dtype=float)).ravel(),
                                   np.zeros(3)])
            Lcomp = np.concatenate([np.atleast_1d(np.asarray(Lcomp_Tx, dtype=float)).ravel(),
                                    np.zeros(3)])
            Cbump = np.array([float(C_bump[0]), 0.0, 0.0, 0.0])
            C_v = np.asarray(param.C_v, dtype=float).ravel()
            Cball = np.array([0.0, 0.0, float(C_v[0]), float(C_pkg_board[0])])
            if pkg_Z_c.ndim == 1:
                Zpkg = pkg_Z_c[:4]
            else:
                Zpkg = pkg_Z_c[0, :4]
        else:
            raise ValueError(f'make_full_pkg: unsupported mele={mele}')
        ch_upper = str(channel_type).upper()
        if ch_upper == 'THRU':
            Len = np.asarray(param.Pkg_len_TX, dtype=float).ravel()
        elif ch_upper == 'NEXT':
            Len = np.asarray(param.Pkg_len_NEXT, dtype=float).ravel()
        elif ch_upper == 'FEXT':
            Len = np.asarray(param.Pkg_len_FEXT, dtype=float).ravel()
        else:
            Len = np.asarray(param.Pkg_len_TX, dtype=float).ravel()
    else:  # RX
        cb1 = float(C_bump[1]) if len(C_bump) > 1 else float(C_bump[0])
        cp1 = float(C_pkg_board[1]) if len(C_pkg_board) > 1 else float(C_pkg_board[0])
        if mele == 1:
            Cpad = np.array([_to_scalar(Cd_Rx)])
            Lcomp = np.array([_to_scalar(Lcomp_Rx)])
            Cbump = np.array([cb1])
            Cball = np.array([cp1])
            zc_vals = pkg_Z_c.ravel()
            Zpkg = np.array([float(zc_vals[1]) if len(zc_vals) > 1 else float(zc_vals[0])])
        elif mele == 4:
            # MATLAB: Cpad=[Cd_Rx 0 0 0]; Lcomp=[Lcomp_Rx 0 0 0] (L8390-8391).
            # Cd_Rx/Lcomp_Rx are ROW VECTORS when C_d/L_comp are a 2xN matrix
            # (N die LC sections per side), so MATLAB yields len(Cd_Rx)+3 entries,
            # matching num_blocks = mele + extra_LC. _to_scalar() kept only the
            # first section, dropping the rest of the die LC network.
            Cpad = np.concatenate([np.atleast_1d(np.asarray(Cd_Rx, dtype=float)).ravel(),
                                   np.zeros(3)])
            Lcomp = np.concatenate([np.atleast_1d(np.asarray(Lcomp_Rx, dtype=float)).ravel(),
                                    np.zeros(3)])
            Cbump = np.array([cb1, 0.0, 0.0, 0.0])
            C_v = np.asarray(param.C_v, dtype=float).ravel()
            cv1 = float(C_v[1]) if len(C_v) > 1 else float(C_v[0])
            Cball = np.array([0.0, 0.0, cv1, cp1])
            if pkg_Z_c.ndim == 1:
                Zpkg = pkg_Z_c[:4]
            else:
                Zpkg = pkg_Z_c[1, :4] if pkg_Z_c.shape[0] > 1 else pkg_Z_c[0, :4]
        else:
            raise ValueError(f'make_full_pkg: unsupported mele={mele}')
        Len = np.asarray(param.Pkg_len_RX, dtype=float).ravel()

    Cball = np.concatenate([insert_zeros, Cball.ravel()])
    Cbump = np.concatenate([insert_zeros, Cbump.ravel()])
    Len = np.concatenate([insert_zeros, Len.ravel()])
    Zpkg = np.concatenate([insert_zeros, Zpkg.ravel()])

    if mode.lower() in ('dc', 'cd'):
        pkg_param.Z0 = float(param.Z0) / 2.0
        Cpad = Cpad * 2.0
        Cball = Cball * 2.0
        Zpkg = Zpkg * 2.0
        Lcomp = Lcomp / 2.0
        Cbump = Cbump * 2.0

    def _el(arr, j):
        a = np.asarray(arr, dtype=float).ravel()
        return float(a[j]) if j < len(a) else 0.0

    n_blocks = int(num_blocks)
    if n_blocks == 1:
        s11o, s12o, s21o, s22o = _s21_pkg__make_pkg(
            faxis, _el(Len, 0), _el(Cpad, 0), _el(Cball, 0), _el(Zpkg, 0),
            pkg_param, _el(Lcomp, 0), _el(Cbump, 0))
    else:
        for j in range(n_blocks):
            sp11, sp12, sp21, sp22 = _s21_pkg__make_pkg(
                faxis, _el(Len, j), _el(Cpad, j), _el(Cball, j), _el(Zpkg, j),
                pkg_param, _el(Lcomp, j), _el(Cbump, j))
            if j == 0:
                s11o, s12o, s21o, s22o = sp11, sp12, sp21, sp22
            else:
                s11o, s12o, s21o, s22o = _s21_pkg__combines4p(s11o, s12o, s21o, s22o, sp11, sp12, sp21, sp22)
    return s11o, s12o, s21o, s22o


def _s21_pkg__bessel(n):
    """Bessel polynomial coefficients (MATLAB lines 4926-4930)."""
    a = np.zeros(n + 1)
    for ii in range(n + 1):
        a[ii] = factorial(2 * n - ii) / (2 ** (n - ii) * factorial(ii) * factorial(n - ii))
    return a


def _s21_pkg__Bessel_Thomson_Filter(param, f, use_BT):
    """Bessel-Thomson filter (MATLAB lines 1028-1035)."""
    f = np.asarray(f, dtype=float)
    if use_BT:
        a = _s21_pkg__bessel(int(param.BTorder))
        acoef = a[::-1]
        H_bt = a[0] / np.polyval(acoef, 1j * f / (float(param.fb_BT_cutoff) * float(param.fb)))
    else:
        H_bt = np.ones(len(f))
    return H_bt


# ---- main function ----------------------------------------------------------

def s21_pkg(chdata, param, OP, channel_number, mode='dd', include_die=1):
    """Compute package-inclusive S21 and VTF (MATLAB lines 10900-11075).

    Returns (s21p, SCH, sigma_ACCM_at_tp0).
    SCH: SimpleNamespace with .Frequencies, .Parameters (2×2×nfreq), .NumPorts, .Impedance.
    sigma_ACCM_at_tp0: scalar (non-zero only in DC mode for channel_number==1).
    """
    if mode is None:
        mode = 'dd'
    mode = str(mode)

    s21 = np.asarray(getattr(chdata, f's{mode}21_raw'), dtype=complex)
    s12 = np.asarray(getattr(chdata, f's{mode}12_raw'), dtype=complex)
    s11 = np.asarray(getattr(chdata, f's{mode}11_raw'), dtype=complex)
    s22 = np.asarray(getattr(chdata, f's{mode}22_raw'), dtype=complex)
    faxis = np.asarray(chdata.faxis, dtype=float)
    channel_type = str(chdata.type)

    if mode.lower() == 'dd':
        s11 = s11 * float(param.kappa1)
        s22 = s22 * float(param.kappa2)

    Z0 = float(param.Z0)
    sigma_ACCM_at_tp0 = 0.0

    R_diepad = np.asarray(param.R_diepad, dtype=float).ravel()

    # TX package
    tx_mode = 'dc' if mode.lower() == 'dc' else 'dd'

    psdrxcal = bool(getattr(OP, 'PSDRXCAL', False))
    num_s4p = int(getattr(param, 'num_s4p_files', 0))

    if psdrxcal and channel_number == num_s4p:
        nf = len(faxis)
        s11out = np.zeros(nf)
        s12out = np.ones(nf)
        s21out = np.ones(nf)
        s22out = np.zeros(nf)
    else:
        s11out, s12out, s21out, s22out = _s21_pkg__make_full_pkg(
            'TX', faxis, param, channel_type, tx_mode, include_die)

    # RX package (always 'dd' unless 'cd' mode)
    rx_mode = 'cd' if mode.lower() == 'cd' else 'dd'
    s11in, s12in, s21in, s22in = _s21_pkg__make_full_pkg(
        'RX', faxis, param, channel_type, rx_mode, include_die)

    # Reflection coefficients
    tx_rd_sel = int(getattr(param, 'Tx_rd_sel', 1)) - 1  # 1-based → 0-based
    rx_rd_sel = int(getattr(param, 'Rx_rd_sel', 2)) - 1

    if mode.lower() == 'dc':
        RTX = float(R_diepad[tx_rd_sel]) / 2.0
        RRX = float(R_diepad[rx_rd_sel])
        Z0gamma_TX = Z0 / 2.0
        Z0gamma_RX = Z0
    elif mode.lower() == 'cd':
        RTX = float(R_diepad[tx_rd_sel])
        RRX = float(R_diepad[rx_rd_sel]) / 2.0
        Z0gamma_TX = Z0
        Z0gamma_RX = Z0 / 2.0
    else:
        RTX = float(R_diepad[tx_rd_sel])
        RRX = float(R_diepad[rx_rd_sel])
        Z0gamma_TX = Z0
        Z0gamma_RX = Z0

    ideal_tx = bool(getattr(OP, 'IDEAL_TX_TERM', False))
    ideal_rx = bool(getattr(OP, 'IDEAL_RX_TERM', False))
    rx_cal = int(getattr(OP, 'RX_CALIBRATION', 0))
    include_pcb = int(getattr(OP, 'include_pcb', 0))

    if ideal_tx or (rx_cal == 1 and channel_number == 2) or include_pcb == 2:
        gamma_tx = 0.0
    else:
        gamma_tx = (RTX - Z0gamma_TX) / (RTX + Z0gamma_TX)

    if ideal_rx:
        gamma_rx = 0.0
    else:
        gamma_rx = (RRX - Z0gamma_RX) / (RRX + Z0gamma_RX)

    inc_pkg = int(getattr(OP, 'INC_PACKAGE', 1))
    nf = len(faxis)

    if inc_pkg == 0:
        import warnings
        warnings.warn('do not use INC_PACKAGE = 0. Instead use package parameters)')
        s21p = s21.copy()
        SCH = SimpleNamespace(
            Frequencies=faxis,
            Parameters=np.zeros((2, 2, nf), dtype=complex),
            NumPorts=2,
            Impedance=Z0 * 2)
        SCH.Parameters[0, 0, :] = s11
        SCH.Parameters[1, 1, :] = s22
        SCH.Parameters[0, 1, :] = s12
        SCH.Parameters[1, 0, :] = s21
        return s21p, SCH, sigma_ACCM_at_tp0

    if rx_cal == 1 and channel_number == 2:
        # Only RX pkg: channel + RX pkg
        s11rx, s12rx, s21rx, s22rx = _s21_pkg__combines4p(
            s11, s12, s21, s22,
            s22out, s12out, s21out, s11out)
        SCH = SimpleNamespace(
            Frequencies=faxis,
            Parameters=np.zeros((2, 2, nf), dtype=complex),
            NumPorts=2,
            Impedance=Z0 * 2)
        SCH.Parameters[0, 0, :] = s11rx
        SCH.Parameters[1, 1, :] = s22rx
        SCH.Parameters[0, 1, :] = s12rx
        SCH.Parameters[1, 0, :] = s21rx
        if include_die:
            s21p = (s21rx * (1 - gamma_tx) * (1 + gamma_rx) /
                    (1.0 - s11rx * gamma_tx - s22rx * gamma_rx
                     - s21rx ** 2 * gamma_tx * gamma_rx
                     + s11rx * s22rx * gamma_tx * gamma_rx))
        else:
            s21p = s21rx
        return s21p, SCH, sigma_ACCM_at_tp0

    # Normal path
    if not ideal_tx:
        s11, s12, s21, s22 = _s21_pkg__combines4p(
            s11out, s12out, s21out, s22out,
            s11, s12, s21, s22)

    # TX filter H_t
    T_r_filter_type = int(getattr(OP, 'T_r_filter_type', 0))
    H_t = np.ones(nf)
    if ideal_tx or T_r_filter_type == 1:
        tr = float(getattr(OP, 'transmitter_transition_time', 0.0))
        if T_r_filter_type == 0:
            H_t = np.exp(-(np.pi * faxis / 1e9 * tr / 1.6832) ** 2)
        else:
            f9 = faxis / 1e9
            meas_point = int(getattr(OP, 'T_r_meas_point', 0))
            if meas_point == 1:
                k = 1.9466 + 7.12 * np.sqrt(1 - 6.51e-3 / tr)
                denom = (f9 ** 4 * (k * tr) ** 4
                         - f9 ** 3 * (k * tr) ** 3 * 10j
                         - 45 * f9 ** 2 * (k * tr) ** 2
                         + f9 * (k * tr) * 105j + 105)
                H_t = 105.0 / denom
            else:
                H_t = np.exp(-2 * (np.pi * f9 * tr / 1.6832) ** 2) * np.exp(-1j * 2 * np.pi * f9 * tr * 3)

    if not ideal_rx:
        s11, s12, s21, s22 = _s21_pkg__combines4p(
            s11, s12, s21, s22,
            s22in, s21in, s12in, s11in)

    if include_die:
        s21p = (H_t * s21 * (1 - gamma_tx) * (1 + gamma_rx) /
                (1.0 - s11 * gamma_tx - s22 * gamma_rx
                 - s21 * s12 * gamma_tx * gamma_rx
                 + s11 * s22 * gamma_tx * gamma_rx))
    else:
        s21p = s21.copy()

    # DC mode: compute AC CM RMS at test point 0
    if mode.lower() == 'dc':
        OP_bt = copy.copy(OP)
        OP_bt.TX_BesselThomson = 1
        H_bt = _s21_pkg__Bessel_Thomson_Filter(param, faxis, 1)
        if channel_number == 1:
            ACCM_max_freq = float(getattr(param, 'ACCM_MAX_Freq', faxis[-1]))
            f_int = faxis[faxis <= ACCM_max_freq]
            nf_int = len(f_int)
            H_cc = s21out[:nf_int] * (1 - gamma_tx) / (1.0 - s11out[:nf_int] * gamma_tx) * H_bt[:nf_int]
            ac_cm_rms = float(getattr(param, 'AC_CM_RMS_TX', 0.0))
            if nf_int > 1 and f_int[-1] > 0:
                sigma_ACCM_at_tp0 = np.sqrt(
                    2 * ac_cm_rms ** 2
                    * np.sum(np.abs(H_cc[1:]) ** 2 * np.diff(f_int))
                    / f_int[-1])

    SCH = SimpleNamespace(
        Frequencies=faxis,
        Parameters=np.zeros((2, 2, nf), dtype=complex),
        NumPorts=2,
        Impedance=(Z0 / 2.0 if mode.lower() in ('dc', 'cd') else Z0 * 2.0))
    SCH.Parameters[0, 0, :] = s11
    SCH.Parameters[1, 1, :] = s22
    SCH.Parameters[0, 1, :] = s12
    SCH.Parameters[1, 0, :] = s21

    return s21p, SCH, sigma_ACCM_at_tp0



# --- s21_to_impulse_DC (MATLAB lines 11076–11146) ---

# ============================================================
# MATLAB→Python translation notes for s21_to_impulse_DC
# MATLAB lines: 11076–11146
# ============================================================
# Converts freq-domain IL to time-domain impulse response.
# Inline: interp_Sparam (MATLAB lines 7950-8165) as _s21_to_impulse_DC__interp_Sparam.
# All-zero IL: returns eps-valued response without calling interp_Sparam.
# Alternating projections for causality enforcement (Quatieri & Oppenheim 1981).
# IL_symmetric: real(IL[0]), IL[1:-1], real(IL[-1]), conj(IL[1:-1]) reversed.
# t_base = k / (freq_step * L).
# Truncation threshold: OP.impulse_response_truncation_threshold.
# ============================================================



def _s21_to_impulse_DC__Tukey_Window(f, param, fr=None, fb=None):
    f = np.asarray(f, dtype=float)
    if fr is None and fb is None:
        fb = float(param.fb)
        fr = float(param.f_r) * float(param.fb)
    fperiod = 2.0 * (float(fb) - float(fr))
    return np.where(
        f < fr, 1.0,
        np.where((f >= fr) & (f <= fb),
                 0.5 * np.cos(2 * np.pi * (f - fb) / fperiod - np.pi) + 0.5,
                 0.0))[:len(f)]


def _s21_to_impulse_DC__interp_extrap(fout, fin, y):
    """interp1(fin, y, fout, 'linear', 'extrap') — extrapolates on the end-segment
    slope rather than clamping the way np.interp does."""
    fout = np.asarray(fout, dtype=float); fin = np.asarray(fin, dtype=float)
    y = np.asarray(y, dtype=float)
    out = np.interp(fout, fin, y)
    if len(fin) >= 2:
        lo = fout < fin[0]
        if np.any(lo):
            out[lo] = y[0] + (y[1] - y[0]) / (fin[1] - fin[0]) * (fout[lo] - fin[0])
        hi = fout > fin[-1]
        if np.any(hi):
            out[hi] = y[-1] + (y[-1] - y[-2]) / (fin[-1] - fin[-2]) * (fout[hi] - fin[-1])
    return out


def _s21_to_impulse_DC__interp_Sparam(Sin, fin, fout, opt_mag, opt_phase, OP, param):
    """Inlined interp_Sparam (MATLAB lines 7950-8165)."""
    Sin = np.asarray(Sin, dtype=complex).ravel()
    fin = np.asarray(fin, dtype=float).ravel()
    fout = np.asarray(fout, dtype=float).ravel()
    eps_val = np.finfo(float).tiny        # tiny/realmin: log-domain guards below
    eps_mag = np.finfo(float).eps         # fix B02-D4 (MATLAB rev 4p15p0 line 8091): machine eps for |S| floor / HF threshold

    H_mag = np.abs(Sin)
    H_mag[H_mag < eps_mag] = eps_mag
    H_ph = np.unwrap(np.angle(Sin))

    if len(H_ph) > 1 and np.mean(np.diff(H_ph)) > 0:
        if getattr(OP, 'DEBUG', False):
            import warnings
            warnings.warn('Anti-causal response found. Finer frequency step is required')
        else:
            raise ValueError('Anti-causal response found. Finer frequency step is required for this channel')

    mag_method = str(opt_mag)
    if mag_method in ('linear_trend_to_DC', 'linear_trend_to_DC_log_trend_to_inf'):
        fin_x = fin.copy(); H_mag_x = H_mag.copy()
        if fin[0] > 0:
            n = min(10, len(fin))
            p = np.polyfit(fin[:n], H_mag[:n], 1)
            fin_x = np.concatenate([[0.0], fin_x])
            H_mag_x = np.concatenate([[float(np.polyval(p, 0))], H_mag_x])
        hf_log = H_mag[-1]
        if fin[-1] < fout[-1]:
            # MATLAB mid_freq_ind = round(length(fin)/2) is a 1-BASED index;
            # floor division as 0-based starts one point late for even len(fin).
            mid = max(0, int(np.floor(len(fin) / 2.0 + 0.5)) - 1)
            with np.errstate(all='ignore'):
                p2 = np.polyfit(fin[mid:], H_mag[mid:], 1)
            hf = float(np.polyval(p2, fout[-1]))
            if hf > H_mag[-1]: hf = H_mag[-1]; hf_log = H_mag[-1]
            elif hf < eps_mag: hf = eps_mag; hf_log = np.finfo(float).tiny  # fix B02-D4 (MATLAB line 8125)
            fin_x = np.concatenate([fin_x, [fout[-1]]])
            H_mag_x = np.concatenate([H_mag_x, [hf]])
        H_mag_i = np.interp(fout, fin_x, H_mag_x)
        if mag_method == 'linear_trend_to_DC_log_trend_to_inf' and fin[-1] < fout[-1]:
            log_x = np.concatenate([np.log(H_mag_x[:-1]), [np.log(max(hf_log, eps_val))]])
            H_lmi = np.exp(np.interp(fout, fin_x, log_x))
            idx = np.searchsorted(fout, fin[-1], side='right')
            H_mag_i[idx:] = H_lmi[idx:]

    elif mag_method == 'trend_to_DC':
        fin_x = fin.copy(); H_mag_x = H_mag.copy()
        if fin[0] > 0:
            n = min(10, len(fin))
            with np.errstate(divide='ignore', invalid='ignore'):
                p = np.polyfit(fin[:n], np.log10(H_mag[:n] + eps_val), 1)
            fin_x = np.concatenate([[0.0], fin_x])
            H_mag_x = np.concatenate([[10.0 ** float(np.polyval(p, 0))], H_mag_x])
        if fin[-1] < fout[-1]:
            # MATLAB mid_freq_ind = round(length(fin)/2) is a 1-BASED index;
            # floor division as 0-based starts one point late for even len(fin).
            mid = max(0, int(np.floor(len(fin) / 2.0 + 0.5)) - 1)
            with np.errstate(divide='ignore', invalid='ignore'):
                p2 = np.polyfit(fin[mid:], np.log10(H_mag[mid:] + eps_val), 1)
            hf = 10.0 ** float(np.polyval(p2, fout[-1]))
            if hf > H_mag[-1]: hf = H_mag[-1]
            fin_x = np.concatenate([fin_x, [fout[-1]]])
            H_mag_x = np.concatenate([H_mag_x, [hf]])
        with np.errstate(divide='ignore', invalid='ignore'):
            H_mag_i = 10.0 ** np.interp(fout, fin_x, np.log10(H_mag_x + eps_val))

    elif mag_method == 'extrap_to_DC_or_zero':
        if fin[0] > 0 and 20 * np.log10(H_mag[0] + eps_val) < -20:
            fin_x2 = np.concatenate([[0.0], fin])
            H_log_x = np.concatenate([[-100.0], np.log10(H_mag)])
            mask = fout <= fin[-1]
            H_mag_i = np.zeros(len(fout))
            H_mag_i[mask] = 10.0 ** np.interp(fout[mask], fin_x2, H_log_x)
        else:
            mask = fout <= fin[-1]; H_mag_i = np.zeros(len(fout))
            with np.errstate(divide='ignore', invalid='ignore'):
                H_mag_i[mask] = 10.0 ** np.interp(fout[mask], fin, np.log10(H_mag))
        H_mag_i[fout > fin[-1]] = H_mag[-1]

    elif mag_method == 'extrap_to_DC':
        mask = fout <= fin[-1]; H_mag_i = np.zeros(len(fout))
        with np.errstate(divide='ignore', invalid='ignore'):
            H_mag_i[mask] = 10.0 ** np.interp(fout[mask], fin, np.log10(H_mag))
        H_mag_i[fout > fin[-1]] = H_mag[-1]

    elif mag_method in ('old', 'pchip'):  # treat 'pchip' as linear fallback
        H_mag_i = np.interp(fout, fin, H_mag)

    else:
        raise ValueError(f'interp_Sparam: invalid opt_interp_Sparam_mag = {mag_method!r}')

    # fix B02-D5 (MATLAB rev 4p15p0 line 8185): interp1(fin,H_ph,fout,'linear','extrap')
    # extends the end-segment slope beyond [fin[0], fin[-1]] instead of clamping.
    H_ph_i = np.interp(fout, fin, H_ph)
    if len(fin) >= 2:
        lo = fout < fin[0]
        H_ph_i[lo] = H_ph[0] + (H_ph[1] - H_ph[0]) / (fin[1] - fin[0]) * (fout[lo] - fin[0])
        hi = fout > fin[-1]
        H_ph_i[hi] = H_ph[-1] + (H_ph[-1] - H_ph[-2]) / (fin[-1] - fin[-2]) * (fout[hi] - fin[-1])
    ph_method = str(opt_phase)

    if ph_method in ('old', 'pchip'):
        H_ph_i = H_ph_i - H_ph_i[0]
    elif ph_method == 'zero_DC':
        H_ph_i[0] = 0.0
    elif ph_method == 'interp_to_DC':
        if fin[0] != 0:
            H_ph_i = np.interp(fout, np.concatenate([[0.0], fin]), np.concatenate([[0.0], H_ph]))
    elif ph_method == 'interp_and_shift_to_DC':
        if fin[0] != 0:
            dc_t = H_ph[0] - (H_ph[1] - H_ph[0]) / (fin[1] - fin[0]) * fin[0] if len(fin) > 1 else 0.0
            H_ph_i = np.interp(fout, np.concatenate([[0.0], fin]),
                                np.concatenate([[0.0], H_ph - dc_t]))
    elif ph_method == 'trend_and_shift_to_DC':
        gd = -np.diff(H_ph) / np.diff(fin)
        n_lf = min(50, len(gd))
        lf = gd[:n_lf]; m = np.median(lf); s = np.std(lf)
        mask_g = np.abs(lf - m) < s
        lf_t = np.mean(lf[mask_g]) if np.any(mask_g) else m
        H_ph_c = H_ph.copy()
        for k in range(min(9, len(fin) - 1), -1, -1):
            H_ph_c[k] = H_ph_c[k + 1] + lf_t * (fin[k + 1] - fin[k])
        if fin[0] != 0:
            dc_t = H_ph_c[0] + lf_t * (fin[0] - 0)
            fin_x = np.concatenate([[0.0], fin]); ph_x = np.concatenate([[0.0], H_ph_c - dc_t])
        else:
            fin_x = fin.copy(); ph_x = H_ph_c.copy()
        if fout[-1] > fin[-1]:
            all_gd = -np.diff(ph_x) / np.diff(fin_x)
            hf_pt = ph_x[-1] - np.median(all_gd) * (fout[-1] - fin_x[-1])
            fin_x = np.concatenate([fin_x, [fout[-1]]]); ph_x = np.concatenate([ph_x, [hf_pt]])
        H_ph_i = np.interp(fout, fin_x, ph_x)
    elif ph_method == 'extrap_cubic_to_dc_linear_to_inf':
        # Full port of MATLAB L8198-8228. This was previously a stub
        # (`np.interp(fout, fin, H_ph)  # simplified: use linear`) that skipped the
        # low-frequency group-delay outlier correction, used the raw phase, and
        # clamped instead of extrapolating. Since this is the CONFIGURED DEFAULT
        # phase method, the LF group delay was wrong on every run, shifting and
        # reshaping the impulse response (peak time off by 53 samples, pulse peak
        # 0.94% high, steady-state 0.46% low).
        # Note MATLAB computes a pchip variant and a blend, then discards both with
        # a final `H_ph_i = H_ph_linear;` — so only the linear branch matters.
        if fin[0] != 0:
            group_delay = -np.diff(H_ph) / np.diff(fin)
            n_lf = min(50, len(group_delay))
            lf_gd = group_delay[:n_lf]
            m_lf = np.median(lf_gd)
            sd_lf = np.std(lf_gd)
            mask_lf = np.abs(lf_gd - m_lf) < sd_lf
            lf_trend = float(np.mean(lf_gd[mask_lf])) if np.any(mask_lf) else float(m_lf)

            # MATLAB: for k=10:-1:1, H_ph(k) = H_ph(k+1) + lf_trend*(fin(k+1)-fin(k))
            H_ph_corr = H_ph.copy()
            for k in range(min(9, len(fin) - 2), -1, -1):
                H_ph_corr[k] = H_ph_corr[k + 1] + lf_trend * (fin[k + 1] - fin[k])

            H_ph_lin = _s21_to_impulse_DC__interp_extrap(fout, fin, H_ph_corr)

            if fout[-1] > fin[-1]:
                n_hf = min(51, len(group_delay))       # MATLAB group_delay(end-50:end)
                hf_gd = group_delay[-n_hf:]
                m_hf = np.median(hf_gd)
                sd_hf = np.std(hf_gd)
                mask_hf = np.abs(hf_gd - m_hf) < sd_hf
                hf_trend = -float(np.mean(hf_gd[mask_hf])) if np.any(mask_hf) else -float(m_hf)
                hf_ext = np.where(fout > fin[-1])[0]
                if len(hf_ext) > 0:
                    last_idx = int(hf_ext[0]) - 1
                    H_ph_lin[hf_ext] = (H_ph_lin[last_idx] +
                                        (fout[hf_ext] - fout[last_idx]) * hf_trend)
            H_ph_i = H_ph_lin
    else:
        raise ValueError(f'interp_Sparam: invalid opt_interp_Sparam_phase = {ph_method!r}')

    H_i = H_mag_i * np.exp(1j * H_ph_i)

    if getattr(OP, 'ZERO_PAD', False):
        zpf = float(getattr(param, 'zero_pad_tukey_window_in_fb', 0))
        fb = float(getattr(param, 'fb', 1.0))
        tl = fin[-1] + zpf * fb; zp = fin[-1]
        if zpf == 0:
            H_tw = np.ones(len(fout))
        elif zpf > 0:
            H_tw = _s21_to_impulse_DC__Tukey_Window(fout, param, fin[-1], tl); zp = tl
        else:
            H_tw = _s21_to_impulse_DC__Tukey_Window(fout, param, tl, fin[-1])
        H_i = H_tw * H_i; H_i[fout > zp] = np.finfo(float).tiny
    return H_i


def _s21_to_impulse_DC__mround(x):
    """MATLAB round(): half away from zero (fix B03-D7, MATLAB rev 4p15p0 line 11232)."""
    return int(np.floor(x + 0.5)) if x >= 0 else int(np.ceil(x - 0.5))


def s21_to_impulse_DC(IL, freq_array, time_step, OP, param):
    """Frequency-domain IL → time-domain impulse response (MATLAB lines 11076-11146).

    IL: complex 1D array
    freq_array: frequency axis in Hz (must have at least 3 points)
    time_step: sample_dt
    OP: options with interp_sparam_mag, interp_sparam_phase, EC_PULSE_TOL, EC_REL_TOL,
        EC_DIFF_TOL, ENFORCE_CAUSALITY, impulse_response_truncation_threshold
    param: parameter namespace

    Returns (voltage, t_base, causality_correction_dB, truncation_dB).
    """
    freq_array = np.asarray(freq_array, dtype=float)
    IL = np.asarray(IL, dtype=complex)

    fmax = 1.0 / time_step / 2.0
    freq_step = (freq_array[2] - freq_array[1])
    # fix B03-D7 (MATLAB rev 4p15p0 line 11232): fout=0:1/round(fmax/freq_step)*fmax:fmax
    # uses MATLAB round (half-away), not Python builtin round (banker's).
    n_steps = max(1, _s21_to_impulse_DC__mround(fmax / freq_step))
    fout = np.arange(0, n_steps + 1) * (fmax / n_steps)

    if np.all(IL == 0):
        IL_interp = np.full(len(fout), np.finfo(float).eps, dtype=complex)
    else:
        IL_interp = _s21_to_impulse_DC__interp_Sparam(
            IL, freq_array, fout,
            getattr(OP, 'interp_sparam_mag', 'extrap_to_DC'),
            getattr(OP, 'interp_sparam_phase', 'interp_to_DC'),
            OP, param)
        # Replace NaN with previous value
        for idx in np.where(np.isnan(IL_interp))[0]:
            IL_interp[idx] = IL_interp[idx - 1] if idx > 0 else np.finfo(float).eps

    IL_col = IL_interp.ravel()
    IL_symmetric = np.concatenate([
        [np.real(IL_col[0])],
        IL_col[1:-1],
        [np.real(IL_col[-1])],
        np.conj(IL_col[1:-1])[::-1]
    ])
    impulse_response = np.real(np.fft.ifft(IL_symmetric))
    L = len(impulse_response)
    t_base = np.arange(L) / (freq_step * L)

    original_impulse_response = impulse_response.copy()

    abs_ir = np.abs(impulse_response)
    half = L // 2
    candidates = np.where(abs_ir[:half] > np.max(abs_ir[:half]) * OP.EC_PULSE_TOL)[0]
    start_ind = int(candidates[0]) if len(candidates) > 0 else 0

    err = np.inf
    while not np.all(impulse_response == 0):
        # fix B03-D6 (MATLAB rev 4p15p0 lines 11260-11261): impulse_response(1:start_ind)=0
        # is 1-based INCLUSIVE, so 0-based candidates[0] must be zeroed too -> [:start_ind+1].
        impulse_response[:start_ind + 1] = 0
        # fix B03-D6 (MATLAB line 11261): impulse_response(floor(L/2):end)=0 -> 0-based [half-1:].
        impulse_response[half - 1:] = 0
        IL_modified = np.abs(IL_symmetric) * np.exp(1j * np.angle(np.fft.fft(impulse_response)))
        ir_modified = np.real(np.fft.ifft(IL_modified))
        delta = np.abs(impulse_response - ir_modified)
        err_prev = err
        # fix B03-D6 (MATLAB line 11267): err = max(delta)/max(impulse_response) uses the
        # SIGNED max, not max(abs(.)).
        peak = np.max(impulse_response)
        err = np.max(delta) / peak if peak != 0 else 0.0
        if err < OP.EC_REL_TOL or abs(err_prev - err) < OP.EC_DIFF_TOL:
            break
        impulse_response = ir_modified

    ir_norm = np.linalg.norm(impulse_response)
    causality_correction_dB = (20 * np.log10(
        np.linalg.norm(impulse_response - original_impulse_response) / ir_norm)
        if ir_norm > 0 else 0.0)

    if not OP.ENFORCE_CAUSALITY:
        impulse_response = original_impulse_response

    ir_peak = np.max(np.abs(impulse_response))
    last_arr = np.where(np.abs(impulse_response) > ir_peak * OP.impulse_response_truncation_threshold)[0]
    ir_last = int(last_arr[-1]) if len(last_arr) > 0 else L - 1

    voltage = impulse_response[:ir_last + 1]
    t_base_out = t_base[:ir_last + 1]

    tail_norm = np.linalg.norm(impulse_response[ir_last + 1:])
    v_norm = np.linalg.norm(voltage)
    truncation_dB = 20 * np.log10(tail_norm / v_norm) if v_norm > 0 and tail_norm > 0 else -np.inf

    return voltage, t_base_out, causality_correction_dB, truncation_dB



# --- s_for_c2 (MATLAB lines 11147–11154) ---

# ============================================================
# MATLAB→Python translation notes for s_for_c2
# MATLAB lines: 11147–11153
# ============================================================
# 1-based vs 0-based: S_Parameters(1,1,:) → params[0,0,:], etc.
# sparameters(): MATLAB RF Toolbox object → SimpleNamespace with
#   .Parameters (2,2,N complex), .Frequencies (N,), .Impedance scalar.
# Formula: shunt capacitor cpad between signal and ground.
#   Y = jωC = j*2π*f*cpad
#   s11 = s22 = -Y*zref / (2 + Y*zref) = -jωC*zref / (2+jωC*zref)
#   s21 = s12 = 2 / (2 + Y*zref)
# Limits: f→0: s11→0, s21→1 (capacitor open at DC) ✓
#         f→∞: s11→-1, s21→0 (capacitor shorted at high freq) ✓
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================


def s_for_c2(zref, f, cpad):
    """2-port S-parameters for a shunt capacitor cpad.

    Returns SimpleNamespace with:
      .Parameters  — (2,2,N) complex array
      .Frequencies — frequency array (N,)
      .Impedance   — reference impedance scalar
    """
    f = np.asarray(f, dtype=float).ravel()
    N = len(f)

    jw_C_Z = 1j * 2.0 * np.pi * f * cpad * zref   # jωC*zref, shape (N,)
    denom = 2.0 + jw_C_Z

    params = np.empty((2, 2, N), dtype=complex)
    params[0, 0, :] = -jw_C_Z / denom    # MATLAB line 11149
    params[1, 1, :] = -jw_C_Z / denom    # MATLAB line 11150
    params[1, 0, :] = 2.0 / denom        # MATLAB line 11151
    params[0, 1, :] = 2.0 / denom        # MATLAB line 11152

    S = SimpleNamespace()
    S.Parameters = params
    S.Frequencies = f
    S.Impedance = zref
    return S



# --- s_for_c4 (MATLAB lines 11155–11164) ---

# ============================================================
# MATLAB→Python translation notes for s_for_c4
# MATLAB lines: 11155–11159
# ============================================================
# External dependencies: s2_to_s4 and snp2smp are NOT in the MATLAB file.
#   They are from the MATLAB RF Toolbox / COM package.
# s2_to_s4(S2): embeds a 2-port S-matrix into a block-diagonal 4-port:
#   S4[0:2, 0:2, :] = S2,  S4[2:4, 2:4, :] = S2,  off-diagonal = 0
# snp2smp(S4, zref, [1 3 2 4]): applies the mixed-mode transformation
#   for port pairs (1,3) and (2,4). For the symmetric block-diagonal case
#   (s11=s22, s12=s21 — a shunt capacitor), this transformation leaves the
#   matrix unchanged (verified analytically via M*S4*M^T = S4 for the
#   standard mixed-mode matrix M).
# Therefore s_for_c4.Parameters is the block-diagonal 4-port of s_for_c2.
# Assumption documented; callers in COM use .Parameters field.
# Output struct: SimpleNamespace with Parameters shape (4,4,N).
# Known discrepancy from prior sicopr.py attempt: none found.
# ============================================================
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "..", ".."))


def s_for_c4(zref, f, cpad):
    """4-port S-parameters for a balanced shunt capacitor cpad.

    Constructs the block-diagonal 4×4 from the 2-port (s_for_c2), then
    applies the mixed-mode transformation snp2smp([1 3 2 4]).  For this
    symmetric network the result equals the block-diagonal itself.
    """
    S2 = s_for_c2(zref, f, cpad)
    s2p = S2.Parameters        # (2, 2, N)
    N = s2p.shape[2]

    # s2_to_s4: block-diagonal embedding
    S4P = np.zeros((4, 4, N), dtype=complex)
    S4P[0:2, 0:2, :] = s2p    # top-left block (ports 1,2)
    S4P[2:4, 2:4, :] = s2p    # bottom-right block (ports 3,4)

    # snp2smp with port pairs (1,3) and (2,4): for this symmetric matrix,
    # the mixed-mode transform M*S4*M^T = S4 (analytically verified).
    params = S4P

    S = SimpleNamespace()
    S.Parameters = params
    S.Frequencies = np.asarray(f, dtype=float).ravel()
    S.Impedance = zref
    return S



# --- save_cmd_line (MATLAB lines 11165–11174) ---

def save_cmd_line(config_file, chdata, num_fext, num_next, cli_name):
    """Build command-line string for running COM interactively (MATLAB lines 11165-11174)."""
    cmd_str = f"{cli_name}('{config_file}',{num_fext}, {num_next},'{chdata[0].filename}'"
    for i in range(1, len(chdata)):
        cmd_str += f",'{chdata[i].filename}'"
    cmd_str += ')'
    return cmd_str



# --- savefigs (MATLAB lines 11175–11215) ---

try:
    import matplotlib.pyplot as plt
    _HAS_MPL = True
except ImportError:
    _HAS_MPL = False


def savefigs(param, OP):
    """Save all open matplotlib figures (MATLAB lines 11175-11215).

    Saves as .fig (pickle) when OP.SAVE_FIGURES==1.
    Saves line data as CSV when OP.SAVE_FIGURE_to_CSV==1.
    Returns list of figure numbers.
    """
    if not _HAS_MPL:
        return []

    fig_nums = plt.get_fignums()
    result_dir = getattr(OP, 'RESULT_DIR', '.')
    runtag = getattr(OP, 'RUNTAG', '')
    base = getattr(param, 'base', '')

    for num in fig_nums:
        fig = plt.figure(num)
        figname = fig.get_label() or ''
        if base and base not in figname:
            figname = f'{figname} {runtag} {base}'.strip()
        figname = f'f_{num}_{figname}'
        figname = figname.replace(':', '-').replace(' ', '_')

        if getattr(OP, 'SAVE_FIGURES', 0) == 1:
            import pickle
            with open(os.path.join(result_dir, figname + '.fig'), 'wb') as fh:
                pickle.dump(fig, fh)

        if getattr(OP, 'SAVE_FIGURE_to_CSV', 0) == 1:
            rows = []
            for ax in fig.get_axes():
                for line in ax.get_lines():
                    rows.append(line.get_xdata())
                    rows.append(line.get_ydata())
            if rows:
                M = np.array(rows)
                np.savetxt(os.path.join(result_dir, figname + '.csv'), M, delimiter=',')

    return fig_nums



