if __name__ == '__main__':
    import argparse
    import sys as _sys
    parser = argparse.ArgumentParser(description='IEEE 802.3 COM calculator')
    parser.add_argument('config_file')
    parser.add_argument('thru_s4p')
    parser.add_argument('--fext', nargs='*', default=[])
    parser.add_argument('--next', nargs='*', default=[])
    parser.add_argument('--export-mat', action='store_true',
                        help='also write a per-case engineering .mat snapshot for R analysis')
    parser.add_argument('--matlab-version', choices=['4p15p0', '4p16p0'],
                        help='which MATLAB release to emulate. Default 4p15p0, the '
                             'version the 208-case reference corpus and the whole '
                             'correlation result were produced with. 4p16p0 enables '
                             'the newer behaviour -- see docs/MATLAB_4p16p0_CHANGES.md')
    parser.add_argument('--eye-under-mlse', action='store_true',
                        help='compute the eye contour and timing bathtub for PLOTTING even '
                             'when MLSE is enabled. MATLAB gates the eye on MLSE == 0 '
                             '(4p15p0 L620), but MLSE is applied afterwards, so the pre-MLSE '
                             '(DFE-only) eye is well defined. Diagnostic only: no reported '
                             'COM, VEC, VEO or EW value changes.')
    args = parser.parse_args()
    if args.matlab_version:
        COM_MATLAB_VERSION = args.matlab_version
        print(f'MATLAB version emulated: {COM_MATLAB_VERSION}')
    if args.eye_under_mlse:
        EYE_PLOT_UNDER_MLSE = True
    _fext = args.fext or []
    _next = args.next or []
    _s4p_files = [args.thru_s4p] + _fext + _next
    _num_fext = len(_fext)
    _num_next = len(_next)
    print(f'Running COM: {args.config_file}')
    print(f'FEXT: {_num_fext}, NEXT: {_num_next}')
    print(f'Files: {_s4p_files}')
    print()
    _results = _run_com(args.config_file, _num_fext, _num_next, _s4p_files,
                        export_mat=args.export_mat)
    if _results is None:
        print('ERROR: COM returned None.')
        _sys.exit(1)
    # com_ieee8023_ unwraps a single-package-case run to a bare struct (matches MATLAB
    # 'if length(results)==1, results = results{1}'). Normalize to a list so the per-case
    # print works for both single- and multi-case configs.
    if not isinstance(_results, list):
        _results = [_results]
    for _i, _r in enumerate(_results):
        if _r is None:
            continue
        print(f'--- Case {_i + 1} ---')
        for _attr in ['COM_dB', 'VEO_mV', 'VEC_dB', 'FOM_ILD', 'ICN_mV']:
            _val = getattr(_r, _attr, 'N/A')
            if isinstance(_val, float):
                print(f'  {_attr:30s} = {_val:.4f}')
            else:
                print(f'  {_attr:30s} = {_val}')
        _thr = float(getattr(_r, 'pass_threshold', 3.0))
        _com = getattr(_r, 'COM_dB', None)
        if _com is not None:
            print(f'  {"Result":30s} = {"PASS" if float(_com) >= _thr else "FAIL"}  (threshold {_thr:.1f} dB)')
        print()
